GROUPS = [
 dict(level='pre-a1',id='LEX-PRE-23',title='Ações e períodos do dia',after='FND-06',words=['eat','drink','sleep','wash','morning','night'],situation='Use cartões com apoio: eat bread = comer pão; drink water = beber água; wash my hands = lavar minhas mãos; sleep = dormir; morning = manhã; night = noite. A tem Morning: eat bread, drink water, wash my hands; Night: sleep. B recebe uma tabela vazia Morning/Night e registra as ações que A aponta e diz. B confirma cada ação com o bloco fornecido. Troquem: Morning: wash my hands, drink tea; Night: eat rice, sleep. No percurso autônomo, cubra o cartão, grave ou escreva os blocos e depois confira a tabela; isso é ensaio.',result='Primeiro cartão: manhã — comer pão, beber água, lavar as mãos; noite — dormir. Segundo: manhã — lavar mãos, beber chá; noite — comer arroz, dormir. Exemplo apoiado: In the morning: eat bread, drink water, wash my hands. At night: sleep. Aceitar apontar e dizer blocos; não exigir narrativa conjugada no pré-A1.',phon='Contraste eat e it apenas como apoio de escuta; o critério é recuperar eat/drink e morning/night no cartão. Não pontuar sotaque.',pitfall='Não traduzir beber por eat nem impor que todos durmam à noite. O calendário é fictício e pode representar trabalho em turnos.'),
 dict(level='pre-a1',id='LEX-PRE-24',title='Tempo e lugar de um encontro',after='FND-06',words=['sunny','rainy','cloudy','warm','outside','inside'],situation='Cartão A: Today: rainy outside; tea inside; warm inside. Cartão B: Tomorrow: cloudy in the morning; sunny later; meeting outside. Apoio: later = depois; meeting = encontro. A informa o próprio cartão com blocos; B registra tempo e lugar. B depois informa seu cartão a A. Diga I don’t understand se faltar compreensão; confirme apontando os termos. Autônomo: faça duas notas separadas hoje/amanhã, confira os cartões e marque quais blocos precisaram de tradução.',result='Hoje: chuvoso fora, chá dentro, ambiente interno descrito como warm. Amanhã: nublado de manhã, ensolarado depois, encontro fora. Cloudy não autoriza acrescentar chuva amanhã. Modelo: Rainy outside. Tea inside. Warm inside. Tomorrow: cloudy, then sunny; meeting outside.',phon='Trabalhe o contraste INside/OUTside com indicação de dois lugares em desenho; confirme se o ouvinte localiza o evento.',pitfall='Cold/hot/warm são descrições relativas; não converter em graus não fornecidos. Não interpretar sunny como garantia para planejar viagem real.'),
 dict(level='a1',id='LEX-A1-18',title='Pedir esclarecimento e corrigir dados',after='A1-08',words=['could you repeat that','what does it mean','how do you spell','is that right','I mean','please write it down'],situation='Cartão A, recepção: nome Lee; room four; Tuesday at ten; closed = fechado. A inicialmente diz room three e corrige com I mean room four. B precisa preencher nome, sala e horário. B pede soletração, repetição da hora, significado de closed, confirma a sala e pede o horário por escrito. A responde L-E-E e fornece os dados do cartão. Inverta com Kim, room two, Friday at twelve, open = aberto; a correção parte de room one. Autônomo: escreva perguntas adequadas às seis dificuldades e compare com o retorno; as respostas do outro papel ficam em cartão separado.',result='Ficha 1: Lee, room four, Tuesday at ten; closed significa fechado. Perguntas-modelo: How do you spell your name? Could you repeat that, please? What does “closed” mean? Room four. Is that right? Please write it down. A: Room three — I mean room four. Ficha 2: Kim, room two, Friday at twelve; open = aberto. Registrar o dado corrigido, não os dois como alternativas.',phon='Use entonação de pergunta audível em Is that right? e pausa antes da correção I mean. O destinatário deve recuperar a informação final.',pitfall='Repetir som, explicar sentido e soletrar resolvem problemas diferentes. Não avaliar apenas se a frase foi decorada.'),
 dict(level='a1',id='LEX-A1-19',title='Organizar uma aula e pedir ajuda para estudar',after='A1-08',words=['lesson','homework','question','answer','page','practise'],situation='A tem recado: English lesson Thursday; homework page twelve, questions one and two; practise with Jo on Friday. B tem uma anotação incorreta: lesson Tuesday, homework page twenty, practise alone. Apoio: alone = sozinho. B faz perguntas e registra correções. A não inventa as respostas do exercício: elas não estão no recado. Troquem usando Monday, page ten, question three, practise with Kim on Wednesday. Autônomo: escreva um recado de quatro linhas e uma pergunta sobre informação ausente.',result='Primeiro: aula quinta; tarefa página 12, perguntas 1 e 2; prática com Jo sexta. As respostas das perguntas não foram fornecidas. Modelo: My lesson is on Thursday. The homework is on page twelve, questions one and two. I practise with Jo on Friday. Can I ask a question? Segundo: Monday, page ten, question three, Kim on Wednesday.',phon='Pratique question e answer em blocos ask a question/write an answer; faça o colega identificar qual campo deve preencher.',pitfall='Não usar homeworks para contar exercícios. Praticar é uma ação; não registrar domínio como consequência automática.'),
 dict(level='a2',id='LEX-A2-17',title='Relatar problemas na moradia',after='A2-05',words=['leak','heating','landlord','tenant','move in','move out'],situation='Cartão do morador: Lee is the tenant; Ana is the landlord. Lee moved in on Monday. On Tuesday Lee noticed a leak in the kitchen and heating that did not work. The cause is unknown. Cartão da recepção: Ana can receive a message; no repair date is confirmed. The previous tenant moved out on Friday. A relata os problemas; B confirma papéis, datas e informação ainda ausente. Escrevam mensagem de 50–70 palavras. Inverta com Jo/Rui, moved in Wednesday, leak in bathroom, previous tenant moved out Monday. Autônomo: leia os cartões em separado, redija e confira cada fato.',result='Modelo: Hello Ana. I moved in on Monday. There is a leak in the kitchen and the heating is not working. I do not know the cause. Could you confirm when someone can check the problems? Please send me a message. Lee, the tenant. A saída do antigo inquilino sexta é fato separado; não prova que causou vazamento. Nenhuma data de reparo deve ser registrada como confirmada.',phon='Contraste moved IN e moved OUT, preservando o sentido mesmo sem imitar redução de fala. Datas devem ser confirmadas pelo interlocutor.',pitfall='Landlord/tenant não são intercambiáveis. O cenário treina comunicação, não aconselhamento legal nem diagnóstico de manutenção.'),
 dict(level='a2',id='LEX-A2-18',title='Descrever caimento e diferenças em uma compra',after='A2-05',words=['loose','tight','cotton','wool','sleeve','pocket'],situation='Pedido: cotton shirt, short sleeves, two pockets. Entrega: label 100% cotton; long sleeves; no pockets; shoulders too tight, body loose. Apoio: shoulders = ombros; body = corpo da peça; label = etiqueta. Cliente explica três diferenças e dois problemas de caimento. Atendente oferece examinar outro modelo, sem garantir troca. Segundo cartão: wool coat, two pockets requested; label 50% wool; one pocket; sleeves too tight. Autônomo: escreva mensagem de 60–80 palavras distinguindo pedido, etiqueta e sensação de caimento.',result='Primeiro produto: material cotton corresponde; mangas longas e ausência de bolsos divergem; ombros apertados e corpo folgado são relatos de caimento. Modelo: I ordered a cotton shirt with short sleeves and two pockets. The label says 100% cotton, but the sleeves are long and there are no pockets. It is too tight at the shoulders and loose around the body. Could I see another model? Segundo: apenas 50% wool, um bolso e mangas apertadas; nenhuma troca confirmada.',phon='Diferencie loose de lose com modelo audível; avalie se o destinatário entende folgado versus apertado. Preserve plural em sleeves/pockets de forma inteligível.',pitfall='Não inferir material pelo toque; não transformar preferência de caimento em defeito comprovado.'),
 dict(level='b1',id='LEX-B1-17',title='Explicar preferências e conferir um pedido de comida',after='B1-08',words=['leftovers','homemade','portion','flavour','spicy','leave out'],situation='Um grupo escreve relato de um almoço. Fonte A: bread described by host as homemade; soup mild, not spicy; Lee requested a small portion and asked to leave out onions. Fonte B: kitchen could not leave out onions; Lee chose another dish; there were leftovers from the meal. Quantities and storage details are not given. Compare as fontes e redija 100–130 palavras para alguém que não estava presente, atribuindo a descrição homemade ao anfitrião. Depois faça diálogo cliente/atendente para um novo pedido: small portion, spicy dish, leave out salt; a possibilidade de alteração precisa ser perguntada. Autônomo: escreva as duas falas e marque que a resposta do restaurante é desconhecida.',result='Relato deve preservar homemade como descrição do anfitrião, mild flavour e not spicy da sopa, pedido de porção pequena, recusa de omitir cebola, escolha de outro prato e sobras sem quantidade. Modelo curto de diálogo: Could I have a small portion? Is it spicy? Could you leave out the salt? Resposta-modelo só para ensaio: I need to check with the kitchen. Não afirmar pedido atendido nem inventar manejo das sobras.',phon='Destaque palavras de contraste mild/not spicy e could/could not no relato. O ouvinte deve identificar o pedido recusado.',pitfall='Não equiparar homemade a saudável, spicy a quente de temperatura, ou pedido de omissão a garantia de ausência de alergênico.'),
 dict(level='b1',id='LEX-B1-18',title='Organizar um relato de saúde sem acrescentar conclusões',after='B1-05',words=['symptom','since','for two days','medical history','follow-up','recover'],situation='Use exclusivamente personagem fictício. Fonte: Today is Thursday. Jo reports tiredness since Monday and a headache for two days. Medical history field is blank. A follow-up is planned for next week, day not confirmed. Jo says, “I am still recovering from an illness.” A transmite o relato à recepção; B confere duração versus início, dados ausentes e status do acompanhamento. Redija 90–120 palavras ou faça relato oral com notas. Autônomo: use os mesmos dados para redigir um resumo e uma pergunta de esclarecimento; não preencha lacunas com experiência pessoal.',result='Modelo: Jo reports tiredness since Monday and a headache for two days. The medical history field is blank, so that information has not been provided. A follow-up is planned for next week, but the day has not been confirmed. Jo says they are still recovering from an illness. Could you confirm the follow-up date? Não atribuir doença específica, recuperação total ou histórico negativo; não transformar a duração de dois dias em horário exato.',phon='Destaque SINCE Monday e FOR two DAYS; preserve still em still recovering. O destinatário registra início, duração e informação ausente separadamente.',pitfall='Blank não significa no history. Avaliar fidelidade do inglês, sem diagnosticar, recomendar tratamento ou solicitar dados pessoais reais.')
]
